sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    //initialize Script Include
    var iawHelper = new x_hsb11_iaw_widget.IAW_Helper();
    var resp;
    var resp_code;
    var resp_body;
    var apiNoResponse = {
        error: "IAW API has failed to respond"
    };

    current.request_date = new GlideDateTime();
    current.state = 2;

    try {
        switch (current.request_type.toString()) {
            case 'CUH':
                resp = iawHelper.cuh_send(current.sn_task, current.ctac_trade_id, current.counterparty_code, current.ctac_allocation_id, current.sub_account_view);
                break;
            case 'ALMH':
                resp = iawHelper.almh_send(current.sn_task, current.ctac_trade_id, current.counterparty_code, current.ctac_allocation_id, current.trading_entity_id, current.buy_sell, current.exchange_id, current.ctac_ctm_trade_detail_fld_comp);
                break;
            case 'MAIH':
                resp = iawHelper.maih_send(current.sn_task, current.block_trade_details, current.client_allocation_details);
                break;
            case 'FCIH':
                resp = iawHelper.fcih_send(current.sn_task, current.ctac_trade_id, current.counterparty_code, current.ctac_trans_msg_p1, current.counterparty_account);
                break;
            case 'BTMH':
                resp = iawHelper.btmh_send(current.sn_task, current.ctac_trade_id, current.counterparty_code, current.trading_entity_id, current.buy_sell, current.exchange_id, current.ctac_ctm_trade_level_fld_comp);
                break;
        }

        resp_code = resp.getStatusCode();
        resp_body = resp.getBody();

		// included code 400 for MSSRBXCE-67 & 432
        if (resp_code == "200" || (resp_code == "400" & (current.request_type.toString()=="ALMH" || current.request_type.toString()=="BTMH"))) 
            current.state = 3;
		else 
            current.state = 4;

        current.response_date = new GlideDateTime();
        current.response_code = resp_code;
        current.response_body = resp_body;

    } catch (err) {
        current.state = 4;
        current.response_code = "None";
        current.response_body = JSON.stringify(apiNoResponse);
    } finally{
		current.update();
	}


})(current, previous);
